-- Admin-managed list-type categories (Lists menu + /lists/<group>/<child> pages). Run this ONE statement in D1 Studio.
CREATE TABLE IF NOT EXISTS taxonomy_nodes (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_slug TEXT NOT NULL DEFAULT '', slug TEXT NOT NULL, name TEXT NOT NULL, menu_name TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT 'mail', short TEXT NOT NULL DEFAULT '', blurb TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'upcoming', compliance TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, menu_visible INTEGER NOT NULL DEFAULT 1, published INTEGER NOT NULL DEFAULT 1, seo_title TEXT NOT NULL DEFAULT '', meta_description TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', product_slugs TEXT NOT NULL DEFAULT '[]', updated_at INTEGER NOT NULL DEFAULT (unixepoch()), UNIQUE (parent_slug, slug));
